parameters.functionScript:
var { OLIVE, OLIVE_ORDER, OLIVE_RUNG_WORD, OLIVE_SHAPE_WORD, olivePickerSlots, oliveWithheld } = Scripts.olive;
var { iwlFirstSeek, iwlReadsEnvelope } = Scripts.requests;
var BAND1 = ["fwd","left","right","water","fill","pick","put","go_nearest","go_to"];
var ALL = ["fwd","left","right","water","fill","pick","put","say","repeat","until","if","when","count_inc","trick","do","ask","go_nearest","go_to","set","change"];
var META = {"fwd":{"kind":"motion","body":false,"count":false,"slots":[]},"left":{"kind":"motion","body":false,"count":false,"slots":[]},"right":{"kind":"motion","body":false,"count":false,"slots":[]},"water":{"kind":"action","body":false,"count":false,"slots":[]},"fill":{"kind":"action","body":false,"count":false,"slots":[]},"pick":{"kind":"action","body":false,"count":false,"slots":[]},"put":{"kind":"action","body":false,"count":false,"slots":[]},"say":{"kind":"ask","body":false,"count":false,"slots":["text"]},"repeat":{"kind":"control","body":true,"count":true,"slots":[]},"until":{"kind":"control","body":true,"count":false,"slots":["sensor","arg"]},"if":{"kind":"control","body":true,"count":false,"slots":["sensor","arg"]},"when":{"kind":"control","body":true,"count":false,"slots":["event"]},"count_inc":{"kind":"control","body":false,"count":false,"slots":[]},"trick":{"kind":"ask","body":true,"count":false,"slots":["name"]},"do":{"kind":"ask","body":false,"count":false,"slots":["name"]},"ask":{"kind":"ask","body":false,"count":false,"slots":["rung","args","shape","dial"]},"go_nearest":{"kind":"motion","body":false,"count":false,"slots":["kind"]},"go_to":{"kind":"motion","body":false,"count":false,"slots":["thing"]},"set":{"kind":"control","body":false,"count":false,"slots":["name","value"]},"change":{"kind":"control","body":false,"count":false,"slots":["name","by"]}};
var LABEL = { fwd: 'Fwd', left: 'Left', right: 'Right', water: 'Water', fill: 'Fill', pick: 'Pick', put: 'Put', say: 'Say', repeat: 'Repeat', until: 'Until', 'if': 'If', when: 'When', count_inc: 'CountInc', trick: 'Trick', 'do': 'Do', ask: 'Ask', go_nearest: 'GoNearest', go_to: 'GoTo', set: 'Set', change: 'Change' };
var band = Number(Inputs.band) === 1 ? 1 : 2;
var allowed = Array.isArray(Inputs.allowed) && Inputs.allowed.length ? Inputs.allowed : null;
var lang = String(Inputs.lang) === 'fr' ? 'fr' : 'en';
// P106 IG-005 (R8): the palette is band × request × ROBOT. Robot is the robot doing the job (a row with its kind and
// palette, or a catalogue kind); it keeps every move, the controls of the band and what it can do. Needs is the kind
// the request asks for: another robot is refused (no palette at all). No robot (free play) filters nothing.
var ROBOTS = [{"id":"pip","defaultName":{"en":"Pip","fr":"Pip"},"colour":"#FF7A59","accessory":"can","palette":["water","fill","olive:read"],"canMax":3,"basket":4,"upgrade":"can+","lentBy":null,"unlockedBy":null},{"id":"cobble","defaultName":{"en":"Cobble","fr":"Cobble"},"colour":"#7A8CA3","accessory":"hod","palette":["pick","put"],"canMax":3,"basket":4,"upgrade":"basket+","lentBy":"sami","unlockedBy":"path-postbox"},{"id":"pocket","defaultName":{"en":"Pocket","fr":"Poche"},"colour":"#FFB347","accessory":"satchel","palette":["pick","put","say","olive:say-thanks","olive:read"],"canMax":3,"basket":6,"upgrade":"boots","lentBy":"biscuit","unlockedBy":"bowl-if"},{"id":"echo","defaultName":{"en":"Echo","fr":"Écho"},"colour":"#8F6BFF","accessory":"bell","palette":["water","fill","say","olive:read","olive:is-it-a","olive:say-thanks"],"canMax":3,"basket":4,"upgrade":"can+","lentBy":"mamie","unlockedBy":"mamie-note"}];
var CAN_ALWAYS = ["fwd","left","right","pick","put","go_nearest","go_to","repeat","until","if","when","count_inc","trick","do","set","change"];
var bot = Inputs.robot && typeof Inputs.robot === 'object' ? Inputs.robot : null;
if (!bot && typeof Inputs.robot === 'string' && Inputs.robot) for (var rk = 0; rk < ROBOTS.length; rk++) if (ROBOTS[rk].id === Inputs.robot) bot = ROBOTS[rk];
var botKind = bot ? String(bot.kind || bot.id || '') : '';
var needs = String(Inputs.needs || '');
var refused = !!bot && needs !== '' && botKind !== needs;
var botCan = bot ? CAN_ALWAYS.concat(Array.isArray(bot.palette) ? bot.palette : []) : null;
var rows = Array.isArray(Inputs.words) ? Inputs.words : [];
var word = {};
for (var i = 0; i < rows.length; i++) word[rows[i].key] = rows[i][lang] || rows[i].en || '';
var ids = band === 1 ? BAND1 : ALL;
var out = [];
for (var j = 0; j < ids.length; j++) {
  var id = ids[j];
  if (allowed && allowed.indexOf(id) === -1) continue;
  if (refused || (botCan && botCan.indexOf(id) === -1)) continue;
  var m = META[id];
  out.push({ id: id, kind: m.kind, label: word['b' + LABEL[id]] || id, caption: word['c' + LABEL[id]] || id, hasBody: m.body, hasCount: m.count, slots: m.slots, band: band });
}
// P108 IW-003 look (lane L): the request, when it is given (the Workshop's Start world) — "go to nearest" starts on the
// first thing THIS job seeks (its reference program's first go to nearest; the drawer said "egg" on the stones and the
// bench), and Olive's read says what it reads there (an envelope where the plot's letters carry a name).
var iwlReq = Inputs.request && typeof Inputs.request === 'object' ? Inputs.request : null;

var iwlSeek = iwlFirstSeek(iwlReq ? iwlReq.referenceProgram : null);
if (iwlSeek) for (var gs = 0; gs < out.length; gs++) if (out[gs].id === 'go_nearest') out[gs].seek = iwlSeek;
// Olive's rungs (CG-005): one entry per rung the request offers ('all' = the ladder), each with its picker. The exam
// gate: a rung this machine's exam FAILED is withheld (the Skills page shows it as "Olive can't do this here yet").
var rungIds = Inputs.rungs === 'all' ? OLIVE_ORDER : Array.isArray(Inputs.rungs) ? Inputs.rungs : [];
var withheld = oliveWithheld(Inputs.exam);
var olive = [], offered = [], heldHere = [];
for (var r = 0; r < rungIds.length; r++) {
  var rid = String(rungIds[r]), rr = OLIVE.rungs[rid];
  // IG-006: only a BLOCK is placed (a lesson is asked on Skills, the voicing is the owl row's).
  if (!rr || rid === 'voice-hint' || rr.use !== 'block' || (Number(rr.band) || 1) > band) continue;
  if (refused || (botCan && botCan.indexOf('olive:' + rid) === -1)) continue;
  if (withheld.indexOf(rid) !== -1) { heldHere.push(rid); continue; }
  offered.push(rid);
  var title = word[OLIVE_RUNG_WORD[rid]] || rid;
  // P108 IW-003 look (lane L): the envelopes' read reads the envelope.
  if (rid === 'read' && iwlReadsEnvelope(iwlReq) && word.iwlReadEnvelope) title = word.iwlReadEnvelope;
  olive.push({ id: 'olive:' + rid, kind: 'ask', label: title, caption: title, hasBody: false, hasCount: false, slots: olivePickerSlots(rid, band, lang, Inputs.narrow, word), band: band, rung: rid, shape: rr.shape, shapeLabel: word[OLIVE_SHAPE_WORD[rr.shape]] || rr.shape, ladder: rr.ladder });
}
if (rungIds.length) { var kept = []; for (var o = 0; o < out.length; o++) if (out[o].id !== 'ask') kept.push(out[o]); out = kept.concat(olive); }
Outputs.palette = out;
Outputs.olive = olive;
Outputs.offered = offered;
Outputs.withheld = withheld;
Outputs.heldHere = heldHere;
Outputs.count = out.length;
Outputs.band = band;
Outputs.refused = refused;
